class Solution:
    # @param A : string
    # @return an integer (1 or 0)
    def solve(self, A):
        stack = []
        pairs = {')': '(', ']': '[', '}': '{'}
        for ch in A:
            if ch in '([{':
                stack.append(ch)
            elif ch in ')]}':
                if not stack or stack[-1] != pairs[ch]:
                    return 0
                stack.pop()
        return 1 if not stack else 0

