module.exports = {
    //param A : string
    //return an integer
    solve: function(A) {
        const stack = [];
        const pairs = { ')': '(', ']': '[', '}': '{' };
        for (let ch of A) {
            if (ch === '(' || ch === '[' || ch === '{') {
                stack.push(ch);
            } else if (ch === ')' || ch === ']' || ch === '}') {
                if (stack.length === 0 || stack[stack.length - 1] !== pairs[ch]) {
                    return 0;
                }
                stack.pop();
            }
        }
        return stack.length === 0 ? 1 : 0;
    }
};

