class Solution:
    # @param A : list of integers
    # @return an integer
    def maxArea(self, A):
        l, r = 0, len(A) - 1
        res = 0
        while l < r:
            res = max(res, min(A[l], A[r]) * (r - l))
            if A[l] < A[r]:
                l += 1
            else:
                r -= 1
        return res

