from collections import deque

class Solution:
    # @param A : integer
    # @param B : list of list of integers
    # @return an integer
    def solve(self, A, B):
        adj = {i: [] for i in range(1, A + 1)}
        for u, v in B:
            adj[u].append(v)

        q = deque([1])
        visited = {1}
        while q:
            curr = q.popleft()
            if curr == A:
                return 1
            for nxt in adj.get(curr, []):
                if nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)
        return 0

