        for (let [u, v] of B) adj.get(u)?.push(v);

        const q = [1];
        const visited = new Set([1]);
        while (q.length > 0) {
            const curr = q.shift();
            if (curr === A) return 1;
            for (let nxt of (adj.get(curr) || [])) {
