class Solution:
    # @param A : integer
    # @return an integer
    def climbStairs(self, A):
        if A <= 2:
            return A
        MOD = 1000000007
        a, b = 1, 2
        for _ in range(3, A + 1):
            a, b = b, (a + b) % MOD
        return b

